import { useEffect, useId, useRef, useState } from 'react';
import { createPortal } from 'react-dom';
import { Icon, type IconName } from '@/components/ui/Icon.js';
import { Burst } from '@/components/ui/Burst.js';
import { prefersReducedMotion } from '@/components/ui/motionPrefs.js';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { serverNow } from '@/lib/serverClock.js';
import { atLeast, useWindowClass } from '@/lib/windowClass.js';
import { CampaignArt } from './art/CampaignArt.js';
import { Seal } from './art/Seal.js';
import { fillCopy } from './campaign.js';
import { BuyButton, BuyFoot, EndedLine, HowItWorks, LegalRow, PlanPicker } from './KeepPro.js';
import { useKeepPro } from './keepProModel.js';
import type { Offer } from './offer.js';
import { sendOfferEvent } from './offerEvents.js';
import { onIOS } from './play.js';
import { PurchaseDone } from './PurchaseDone.js';
import { usePurchase } from './purchase.js';
import { useBilling } from './state.js';
import { runningTrial } from './trial.js';
import { useAppStoreRestore } from './useAppStoreRestore.js';
import { useOfferWords } from './useOfferWords.js';
import { isMomentOffer } from './moment.js';
import { noteSellingShown } from './sellingSignals.js';
import kp from './KeepPro.module.css';
import { badgeWords, countdownLabel } from './planChoices.js';
import styles from './OfferPaywall.module.css';

const PERKS: {
  icon: IconName;
  tint: string;
  title: 'perk.lex' | 'perk.read' | 'perk.practice' | 'perk.cards';
  line: 'perk.lexLine' | 'perk.readLine' | 'perk.practiceLine' | 'perk.cardsLine';
}[] = [
  { icon: 'sparkles', tint: 'a', title: 'perk.lex', line: 'perk.lexLine' },
  { icon: 'search', tint: 'g', title: 'perk.read', line: 'perk.readLine' },
  { icon: 'speaker', tint: 'i', title: 'perk.practice', line: 'perk.practiceLine' },
  { icon: 'cards', tint: 't', title: 'perk.cards', line: 'perk.cardsLine' },
];

/**
 * The full-screen offer (uiux offers spec §2.5, C14): the campaign's
 * entrance, and "See my offer" from its banner. Art band (or the tall art
 * panel beside the content on a wide screen), kicker, title, the plans
 * with the offer's live countdown, perks, how it works, legal lines; the
 * button, the trust row and the legal sentence in a sticky bar, so on a
 * 390×844 phone the chosen plan and its terms are in view without
 * scrolling. Close is visible from the first frame. A dialog: focus moves
 * in, Escape closes, focus goes back.
 */
export function OfferPaywall({
  offer,
  surface,
  onClose,
}: {
  offer: Offer;
  surface: 'fullscreen' | 'today_banner';
  onClose: () => void;
}): React.JSX.Element {
  const state = useBilling((s) => s.state);
  const refresh = useBilling((s) => s.refresh);
  const purchase = usePurchase();
  const restore = useAppStoreRestore(purchase.finish);
  // The end passed while it was open: the offer's card goes at once, the
  // prices of today take its place (§4.1, moment offer §10.1).
  const [ended, setEnded] = useState(false);
  const model = useKeepPro(ended ? undefined : offer);
  const words = useOfferWords(offer);
  const moment = isMomentOffer(offer);
  const size = useWindowClass();
  const wide = atLeast(size, 'expanded');
  const creative = offer.creative;
  const titleId = useId();
  const trustId = useId();
  const legalId = useId();
  const panel = useRef<HTMLDivElement>(null);
  const close = useRef(onClose);
  useEffect(() => {
    close.current = onClose;
  });
  const [now] = useState(() => new Date(serverNow()));
  const trial = runningTrial(state, now) !== undefined;
  const hasArt = creative?.images.some((image) => image.role === (wide ? 'hero_tall' : 'banner')) === true;
  const confetti = creative?.look.motion === 'confettiOnOpen' && !prefersReducedMotion();

  useEffect(() => {
    const restoreTo = document.activeElement instanceof HTMLElement ? document.activeElement : null;
    panel.current?.focus();
    const onKey = (event: KeyboardEvent): void => {
      if (event.key === 'Escape') {
        event.stopPropagation();
        close.current();
      }
    };
    document.addEventListener('keydown', onKey);
    const overflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    return () => {
      document.removeEventListener('keydown', onKey);
      document.body.style.overflow = overflow;
      restoreTo?.focus();
    };
  }, []);

  useEffect(() => {
    noteSellingShown();
    sendOfferEvent(offer.id, 'shown', surface === 'fullscreen' ? 'fullscreen' : 'offer_sheet', {
      ...(creative === undefined ? {} : { campaignId: creative.campaignId, variantId: creative.variantId }),
    });
    // Once per opening.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const title =
    (moment && words !== undefined ? t('moment.banner.title', { amount: words.first }) : undefined) ??
    fillCopy(creative?.headline, { firstPeriodPrice: words?.first, renewalPrice: words?.renewal }) ??
    t('paywall.titleOffer');
  // A moment offer says it is made once (true: the server gives it once).
  const subline = moment
    ? t('moment.once')
    : fillCopy(creative?.subline, {
        firstPeriodPrice: words?.first,
        renewalPrice: words?.renewal,
      });
  const badge = model.choices.find((one) => one.offer !== undefined)?.badge;
  const look = creative?.look;

  const done = purchase.stage !== 'choosing' || purchase.approved;
  const art = hasArt ? (
    <div className={styles.art}>
      <CampaignArt
        role={wide ? 'hero_tall' : 'banner'}
        creative={creative}
        sizes={wide ? '400px' : 'calc(100vw - 24px)'}
        priority
        house={
          wide
            ? { width: 800, height: 1440, fx: 0.42, fy: 0.5, fit: 'xMidYMid slice' }
            : { width: 1200, height: 600, fx: 0.7, fy: 0.55, fit: 'xMidYMid slice' }
        }
      />
    </div>
  ) : null;

  return createPortal(
    <div className={styles.backdrop}>
      <div
        className={cx(styles.panel, !hasArt && styles.noArt)}
        role="dialog"
        aria-modal="true"
        aria-labelledby={titleId}
        tabIndex={-1}
        ref={panel}
      >
        {wide && art}
        <div className={styles.side}>
          <button type="button" className={styles.close} aria-label={t('paywall.close')} onClick={onClose}>
            <Icon name="close" size={20} weight={2} />
          </button>
          <div className={styles.scroll}>
            {!wide && art}
            {done ? (
              <div className={styles.body}>
                <h2 id={titleId} className="sr-only">
                  {t('done.title')}
                </h2>
                <PurchaseDone purchase={purchase} onDone={onClose} />
              </div>
            ) : (
              <div className={styles.body}>
                {confetti && (
                  <span className={styles.burst} aria-hidden="true">
                    <Burst size="small" />
                  </span>
                )}
                <span className={styles.kicker}>
                  <Seal size={14} />
                  {badge === 'early_price'
                    ? t('paywall.kickerEarly')
                    : badge !== undefined && badge !== 'best_value'
                      ? badgeWords(badge, offer)
                      : t('paywall.kicker')}
                </span>
                <h2 id={titleId} className={styles.title}>
                  {title}
                </h2>
                {subline !== undefined && !ended && <p className={styles.lead}>{subline}</p>}
                {ended && <EndedLine />}
                {purchase.notice !== null && (
                  <p className={styles.notice} role="status">
                    {purchase.notice}
                  </p>
                )}
                <PlanPicker
                  model={model}
                  legend={trial ? t('pick.legend') : t('pick.legendGet')}
                  legendHidden
                  disabled={purchase.busy !== null}
                  countdown={{
                    surface: 'opened',
                    label: countdownLabel(badge),
                    liveSecondsFromHours: look?.liveSecondsFromHours ?? 24,
                    style: moment ? 'moment' : (look?.countdownStyle ?? 'auto'),
                    pips: !moment,
                    onEnded: () => {
                      setEnded(true);
                      void refresh();
                    },
                  }}
                />
                <ul className={styles.perks}>
                  {PERKS.map((perk) => (
                    <li key={perk.title}>
                      <span className={cx(styles.perkIcon, styles[`tint_${perk.tint}`])} aria-hidden="true">
                        <Icon name={perk.icon} size={18} />
                      </span>
                      <span>
                        {t(perk.title)}
                        <small>{t(perk.line)}</small>
                      </span>
                    </li>
                  ))}
                </ul>
                {model.choice !== undefined && <HowItWorks choice={model.choice} trial={trial} now={now} />}
                <LegalRow
                  store={model.store}
                  restore={onIOS() ? restore : undefined}
                  disabled={purchase.busy !== null}
                />
              </div>
            )}
          </div>
          {!done && (
            <div className={styles.bar}>
              <BuyButton
                model={model}
                trial={trial}
                busy={purchase.busy !== null}
                disabled={purchase.busy !== null}
                describedBy={`${trustId} ${legalId}`}
                onBuy={(choice) => {
                  purchase.buy(choice.id, choice.offer, { billed: choice.billed, renewal: choice.renewal });
                }}
              />
              {purchase.error !== null && (
                <p className={kp.trust} role="alert">
                  {purchase.error}
                </p>
              )}
              <BuyFoot model={model} trial={trial} ids={{ trust: trustId, legal: legalId }} />
              {moment && !ended && <p className={kp.trust}>{t('moment.doNothing')}</p>}
            </div>
          )}
        </div>
      </div>
    </div>,
    document.body,
  );
}
